        body: 'تسجيل السكن، أو Anmeldung، هو تسجيل عنوانك رسميًا لدى البلدية في المدينة التي تسكن فيها. تحتاج إليه عندما تنتقل إلى ألمانيا لأول مرة، أو عندما تغيّر السكن داخل ألمانيا إلى شقة أو غرفة أو عنوان جديد.\n\nبعد التسجيل تحصل على ورقة إثبات العنوان، وتسمى غالبًا Meldebescheinigung. هذه الورقة مهمة جدًا، لأنك قد تحتاجها لفتح حساب بنكي، أو التسجيل في التأمين الصحي، أو التعامل مع الجامعة، أو صاحب العمل، أو الدوائر الحكومية.',
