        body: 'إذا كان برنامجك الدراسي في ألمانيا يُدرّس باللغة الألمانية، فغالبًا ستحتاج إلى شهادة لغة تثبت أنك قادر على متابعة المحاضرات وكتابة الواجبات والمشاركة في النقاشات الأكاديمية. أكثر الشهادات التي تظهر في شروط الجامعات هي TestDaF وDSH وtelc C1 Hochschule، إضافة إلى شهادات Goethe في بعض الحالات.\n\nلا توجد شهادة واحدة تصلح لكل الجامعات والبرامج. القرار النهائي دائمًا يكون في صفحة البرنامج أو مكتب القبول في الجامعة، لذلك ابدأ من شرط اللغة المكتوب في إعلان البرنامج قبل حجز أي امتحان.',
