        body: 'الحساب البنكي المغلق، أو Sperrkonto، هو حساب خاص يثبت للجهات الألمانية أن لديك مبلغًا كافيًا لتغطية مصاريفك خلال فترة الإقامة، خصوصًا عند التقديم لتأشيرة الدراسة أو بعض أنواع الإقامة التي تحتاج إثبات تمويل.\n\nفكرته بسيطة: تضع مبلغًا محددًا في الحساب قبل السفر أو قبل تجديد الإقامة، وبعد الوصول إلى ألمانيا لا تستطيع سحب المبلغ كله مرة واحدة، بل يتم تحويل مبلغ شهري لك حسب القواعد المتفق عليها.',
