        body: 'غالبًا يحتاجه الطلاب الدوليون عند إثبات التمويل للسفارة أو مكتب الأجانب. وقد تحتاجه أيضًا إذا لم يكن لديك منحة، كفيل رسمي، أو إثبات تمويل آخر تقبله الجهة المختصة.\n\nلا تفتح الحساب بناءً على تجربة شخص آخر فقط. راجع صفحة السفارة أو مكتب الأجانب لمعرفة المبلغ المطلوب والمدة المطلوبة، لأن المتطلبات قد تتغير حسب نوع التأشيرة وسنة التقديم.',
