        body: 'تعتبر منحة DW Akademie للماجستير في الإعلام فرصة ذهبية للطلاب الطموحين الراغبين في تطوير مهاراتهم في مجال الإعلام والمساهمة في بناء مستقبل إعلامي مستقل ومهني. تقدم هذه المنحة، التي تمول بالكامل، تجربة تعليمية فريدة في واحدة من أبرز المؤسسات الإعلامية في العالم.',
