        body: 'احجز الامتحان بعد أن تعرف الدرجة المطلوبة بدقة، واترك وقتًا كافيًا لظهور النتيجة وإرسالها للجامعة. إذا كان لديك أكثر من برنامج، اجمع شروط اللغة في جدول واحد واختر الامتحان الذي تقبله كل الجامعات التي تستهدفها قدر الإمكان.\n\nإذا كان الشرط غير واضح، راسل مكتب القبول باسم الامتحان الكامل قبل الدفع. هذه خطوة صغيرة لكنها توفر عليك رسوم امتحان ووقتًا ثمينًا.',
